<script module lang="ts">
/**
 * Time left until a moment, ticking each second (`design/components/countdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/countdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy } from 'svelte'

import {
  countdownClock,
  countdownLeft,
  countdownMoment,
  countdownSpoken,
  devWarning,
  followCountdown,
  joinSlot,
  watchEffect,
} from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/countdown.module.css'

export interface CountdownMessages {
  mark: (label: string, time: string) => string
}

export interface CountdownProps {
  /**
   * Says the time left in a polite line at one minute and at ten seconds. Off, nothing is said.
   */
  announce?: boolean
  /**
   * What it counts to, for assistive technology: "Time until you can send a new code".
   */
  label: string
  /**
   * The locale `Intl` writes the digits and the words in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CountdownMessages
  /**
   * Called once when the moment is reached, and once after mount when it has already passed.
   */
  onEnd?: () => void
  /**
   * The moment it counts to: an ISO-8601 instant, as RelativeTime reads its value. Not a number
   * of seconds, which would start again on every render. A server's "retry after 30" becomes a
   * moment once, where the app receives it.
   */
  until: string
}
</script>

<script lang="ts">
let { announce = false, label: labelOwn, locale, messages, onEnd, until }: CountdownProps = $props()
const joined = joinSlot(undefined, () => ({ label: labelOwn }))
const label = $derived(
  joined.passed['label'] === undefined ? labelOwn : (joined.passed['label'] as typeof labelOwn),
)
let reading = $state(null as { at: number; left: number } | null)
let said = $state(null as { at: number; text: string } | null)
let ended = $state(null as number | null)
const moment = $derived(countdownMoment(until))
const say = $derived(messages ?? { mark: (label: string, time: string) => label + ': ' + time })
const time = $derived({
  left:
    reading !== null && reading.at === moment
      ? reading.left
      : moment === null
        ? 0
        : countdownLeft(moment),
})
const heard = $derived(said !== null && said.at === moment ? said.text : '')
const heed = $derived((at: number) => (left: number, marked: boolean): void => {
  reading = { at: at, left: left }
  if (marked && announce) said = { at: at, text: say.mark(label, countdownSpoken(left, locale)) }
  if (left === 0 && ended !== at) {
    ended = at
    onEnd?.()
  }
})
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  const ran = moment === null ? undefined : followCountdown(moment, heed(moment))
  release1 = () => {
    ran?.()
  }
}
watchEffect(effect1, { watch: () => moment })
onDestroy(() => release1?.())
const effect2 = () => {
  devWarning(
    moment === null,
    `Countdown could not read "${until}" as a moment — rendering nothing.`,
  )
}
watchEffect(effect2, { watch: () => moment })
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if moment !== null
    }<span
      class={styles.countdown}
      data-ended={(time.left === 0) ? '' : undefined}
      data-allow-mismatch="attribute"
      data-member="countdown"
      ><time
        role="timer"
        aria-label={label}
        datetime={'PT' + time.left + 'S'}
        data-allow-mismatch="text,attribute"
        ><span class={styles.digits} aria-hidden="true">{countdownClock(time.left, locale)}</span
        ><span class={styles.spoken}>{countdownSpoken(time.left, locale)}</span
      ></time
      >{#if announce}<span class={styles.spoken} role="status">{heard}</span>{/if
    }</span
  >{/if
}{/if
}{@render joined.end?.()}
